const transitionMembership = `-- name: TransitionMembership :one
UPDATE organization_memberships SET lifecycle_state = $3,
  joined_at = CASE WHEN $3 = 'active' AND joined_at IS NULL THEN now() ELSE joined_at END
WHERE id = $1 AND organization_id = $2 AND lifecycle_state = ANY($4::text[])
RETURNING id, user_id
`

type TransitionMembershipParams struct {
	ID             pgtype.UUID `json:"id"`
	OrganizationID pgtype.UUID `json:"organization_id"`
	LifecycleState string      `json:"lifecycle_state"`
	Column4        []string    `json:"column_4"`
}

type TransitionMembershipRow struct {
	ID     pgtype.UUID `json:"id"`
	UserID pgtype.UUID `json:"user_id"`
}

// Guarded lifecycle write: fires only while the membership still holds an
// expected source state — a stale read can't regress or double-transition.
// joined_at stamps on first activation (invite path already stamps on
// CreateMembership; the application pipeline lands it here).
func (q *Queries) TransitionMembership(ctx context.Context, arg TransitionMembershipParams) (TransitionMembershipRow, error) {
	row := q.db.QueryRow(ctx, transitionMembership,
		arg.ID,
		arg.OrganizationID,
		arg.LifecycleState,
		arg.Column4,
	)
	var i TransitionMembershipRow
	err := row.Scan(&i.ID, &i.UserID)
	return i, err
}

const withdrawApplication = `-- name: WithdrawApplication :one
UPDATE membership_applications SET status = 'withdrawn', decided_at = now()
WHERE id = $1 AND user_id = $2 AND status IN ('applied','screened')
RETURNING id, organization_id
`

type WithdrawApplicationParams struct {
	ID     pgtype.UUID `json:"id"`
	UserID pgtype.UUID `json:"user_id"`
}

type WithdrawApplicationRow struct {
	ID             pgtype.UUID `json:"id"`
	OrganizationID pgtype.UUID `json:"organization_id"`
}

// Self-service withdrawal: only the applicant's own row, and only while
// pre-decision. CAS source states keep a raced admin decision from
// being clobbered.
func (q *Queries) WithdrawApplication(ctx context.Context, arg WithdrawApplicationParams) (WithdrawApplicationRow, error) {
	row := q.db.QueryRow(ctx, withdrawApplication, arg.ID, arg.UserID)
	var i WithdrawApplicationRow
	err := row.Scan(&i.ID, &i.OrganizationID)
	return i, err
}
